1	/* Cal.com inline embed bootstrap for the booking section on /services.
2	   External file (rather than an inline <script>) so the site CSP can serve
3	   script-src without 'unsafe-inline'; app.cal.com is the only third-party
4	   origin involved and is allowlisted in public/_headers. */
5	(function () {
6		'use strict';
7	
8		var mount = document.getElementById('cal-booking');
9		if (!mount) return;
10		var calLink = mount.getAttribute('data-cal-link');
11		if (!calLink) return;
12	
13		/* Mount only once the booking section approaches the viewport. The embed
14		   pulls ~1.7MB across ~70 requests from app.cal.com, which would otherwise
15		   dominate the page's byte weight for visitors who never scroll this far.
16		   Same idea as analytics.js deferring Umami until first interaction. */
17		var booted = false;
18		function boot() {
19			if (booted) return;
20			booted = true;
21	
22			/* Official Cal.com embed loader snippet (queues calls until embed.js loads). */
23			(function (C, A, L) {
24				var p = function (a, ar) { a.q.push(ar); };
25				var d = C.document;
26				C.Cal = C.Cal || function () {
27					var cal = C.Cal;
28					var ar = arguments;
29					if (!cal.loaded) {
30						cal.ns = {};
31						cal.q = cal.q || [];
32						d.head.appendChild(d.createElement('script')).src = A;
33						cal.loaded = true;
34					}
35					if (ar[0] === L) {
36						var api = function () { p(api, arguments); };
37						var namespace = ar[1];
38						api.q = api.q || [];
39						if (typeof namespace === 'string') {
40							cal.ns[namespace] = cal.ns[namespace] || api;
41							p(cal.ns[namespace], ar);
42							p(cal, ['initNamespace', namespace]);
43						} else {
44							p(cal, ar);
45						}
46						return;
47					}
48					p(cal, ar);
49				};
50			})(window, 'https://app.cal.com/embed/embed.js', 'init');
51	
52			/* Match the site's effective theme. theme.js stamps data-theme on <html>
53			   before this runs; fall back to the same explicit-choice-then-OS logic
54			   if it didn't load. */
55			var dark = document.documentElement.getAttribute('data-theme') === 'dark';
56			if (!document.documentElement.hasAttribute('data-theme')) {
57				try {
58					var stored = localStorage.getItem('darkMode');
59					dark = stored === 'enabled' ||
60						(stored !== 'disabled' && window.matchMedia('(prefers-color-scheme: dark)').matches);
61				} catch (e) {
62					/* localStorage unavailable — keep the light theme */
63				}
64			}
65	
66			window.Cal('init', { origin: 'https://app.cal.com' });
67			window.Cal('inline', {
68				elementOrSelector: '#cal-booking',
69				calLink: calLink,
70				config: { theme: dark ? 'dark' : 'light' },
71			});
72			window.Cal('ui', {
73				hideEventTypeDetails: false,
74				cssVarsPerTheme: {
75					light: { 'cal-brand': '#1a5276' },
76					dark: { 'cal-brand': '#60a5fa' },
77				},
78			});
79		}
80	
81		if ('IntersectionObserver' in window) {
82			var io = new IntersectionObserver(function (entries) {
83				for (var i = 0; i < entries.length; i++) {
84					if (entries[i].isIntersecting) {
85						io.disconnect();
86						boot();
87						return;
88					}
89				}
90			}, { rootMargin: '400px 0px' });
91			io.observe(mount);
92		} else {
93			boot();
94		}
95	})();

