429	describe('contact form: branded emails', () => {
430	  // A fetch stub that also captures the JSON bodies POSTed to ForwardEmail so
431	  // the tests can assert on the rendered notification and auto-reply.
432	  function stubAndCapture() {
433	    const mails: Array<Record<string, unknown>> = [];
434	    const fetchSpy = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
435	      const url = typeof input === 'string' ? input : input instanceof URL ? input.toString() : input.url;
436	      if (url.includes('challenges.cloudflare.com/turnstile/v0/siteverify')) {
437	        return new Response(JSON.stringify({ success: true, 'error-codes': [] }), {
438	          status: 200,
439	          headers: { 'Content-Type': 'application/json' },
440	        });
441	      }
442	      if (url.includes('api.forwardemail.net/v1/emails')) {
443	        if (init?.body) mails.push(JSON.parse(String(init.body)));
444	        return new Response('{"id":"abc123"}', { status: 200 });
445	      }
446	      throw new Error(`Unexpected fetch in test: ${url}`);
447	    });
448	    vi.stubGlobal('fetch', fetchSpy);
449	    return mails;
450	  }
451	
452	  it('sends the owner notification as branded HTML with a plain-text part', async () => {
453	    const mails = stubAndCapture();
454	    const ctx = createExecutionContext();
455	    const res = await worker.fetch(makeContactRequest(), env, ctx);
456	    await waitOnExecutionContext(ctx);
457	    expect(res.status).toBe(303);
458	
459	    const notification = mails.find(m => String(m.subject).startsWith('Contact form:'));
460	    expect(notification).toBeDefined();
461	    // Goes to the owner, reply routes back to the sender. The display-name is
462	    // quoted (RFC 5322) so a crafted name can't smuggle a second address.
463	    expect(notification!.to).toBe(env.CONTACT_TO);
464	    expect(notification!.replyTo).toBe('"Test User" <test@example.com>');
465	    // Branded HTML: the site's Indigo primary and the sender's details.
466	    expect(String(notification!.html)).toContain('#3F51B5');
467	    expect(String(notification!.html)).toContain('New contact form submission');
468	    expect(String(notification!.html)).toContain('test@example.com');
469	    // Still ships a text/plain alternative for non-HTML clients.
470	    expect(String(notification!.text)).toContain('Hello there, this is a test message.');
471	  });
472	
473	  it('sends a branded thank-you auto-reply back to the sender', async () => {
474	    const mails = stubAndCapture();
475	    const ctx = createExecutionContext();
476	    const res = await worker.fetch(makeContactRequest(), env, ctx);
477	    await waitOnExecutionContext(ctx);
478	    expect(res.status).toBe(303);
479	
480	    const autoReply = mails.find(m => String(m.subject).includes('Thanks for reaching out'));
481	    expect(autoReply).toBeDefined();
482	    // Delivered to the person who filled out the form...
483	    expect(autoReply!.to).toBe('test@example.com');
484	    // ...from the site address, with replies routed to the owner.
485	    expect(autoReply!.from).toBe(env.CONTACT_FROM);
486	    expect(autoReply!.replyTo).toBe(env.CONTACT_TO);
487	    // Warm, branded, and on-message.
488	    expect(String(autoReply!.html)).toContain('#3F51B5');
